const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Great Fox Island, Alaska (Aleutian Islands)
  const foxIsland = ee.Geometry.Point([-166.3, 52.9]).buffer(5000); // 5km buffer

  const date1999Start = '1999-05-01';
  const date1999End = '1999-09-30';
  const date2019Start = '2019-05-01';
  const date2019End = '2019-09-30';

  // 2. Data Acquisition for 1999 (Landsat 5)
  let col1999 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(foxIsland)
    .filterDate(date1999Start, date1999End)
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let size1999 = col1999.size().getInfo();
  console.log(`1999 Images found: ${size1999}`);

  if (size1999 === 0) {
    // Try wider date range
    col1999 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(foxIsland)
      .filterDate('1999-01-01', '1999-12-31')
      .filter(ee.Filter.lt('CLOUD_COVER', 50));
    size1999 = col1999.size().getInfo();
    console.log(`1999 Images (wider range): ${size1999}`);

    if (size1999 === 0) {
      console.log('No data for 1999');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Data Acquisition for 2019 (Landsat 8)
  let col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(foxIsland)
    .filterDate(date2019Start, date2019End)
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let size2019 = col2019.size().getInfo();
  console.log(`2019 Images found: ${size2019}`);

  if (size2019 === 0) {
    col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(foxIsland)
      .filterDate('2019-01-01', '2019-12-31')
      .filter(ee.Filter.lt('CLOUD_COVER', 50));
    size2019 = col2019.size().getInfo();
    console.log(`2019 Images (wider range): ${size2019}`);

    if (size2019 === 0) {
      console.log('No data for 2019');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Processing - Create median composites and calculate land area
  const img1999 = col1999.median().multiply(0.0000275).add(-0.2); // Scale factors for L5
  const img2019 = col2019.median().multiply(0.0000275).add(-0.2); // Scale factors for L8

  // Calculate NDWI for water detection (Green - NIR) / (Green + NIR)
  const ndwi1999 = img1999.normalizedDifference(['SR_B2', 'SR_B4']); // Green, NIR
  const ndwi2019 = img2019.normalizedDifference(['SR_B3', 'SR_B5']); // Green, NIR for L8

  // Land mask: NDWI < 0 indicates land
  const land1999 = ndwi1999.lt(0);
  const land2019 = ndwi2019.lt(0);

  // 5. Calculate land area (count land pixels)
  const stats1999 = land1999.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: foxIsland,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2019 = land2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: foxIsland,
    scale: 3000,
    maxPixels: 1e9
  });

  const landPixels1999 = stats1999.get('nd').getInfo();
  const landPixels2019 = stats2019.get('nd').getInfo();

  console.log(`Land pixels 1999: ${landPixels1999}`);
  console.log(`Land pixels 2019: ${landPixels2019}`);

  // 6. Validation & Final Answer
  if (landPixels1999 === null || landPixels2019 === null) {
    console.log('Calculation failed - null values');
    console.log('<answer>C3</answer>');
    return;
  }

  if (landPixels1999 === 0 || landPixels2019 === 0) {
    console.log('No valid land pixels detected');
    console.log('<answer>C2</answer>');
    return;
  }

  const pixelArea = 3000 * 3000; // m²
  const area1999 = (landPixels1999 * pixelArea) / 1e6; // km²
  const area2019 = (landPixels2019 * pixelArea) / 1e6; // km²
  const change = area2019 - area1999;

  console.log(`Land area 1999: ${area1999.toFixed(2)} km²`);
  console.log(`Land area 2019: ${area2019.toFixed(2)} km²`);
  console.log(`Change: ${change.toFixed(2)} km²`);

  if (area2019 < area1999) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
